"""Fixed frozen-template PNG, RGB inverted with unchanged alpha; no file/network I/O."""
import base64
import hashlib
from html.parser import HTMLParser

SOURCE_PNG_SHA256 = '8c720ad4300f55469cb30154004aacbc93f8945dc01d1438181f4bcd342d97ea'
CALLIGRAPHY_SHA256 = 'ff583af5f822788b1ada58aa4dcac5a342d9cd01eb47e0c61a4b6975e09bdaaa'
CALLIGRAPHY_CID = 'anxin-calligraphy-' + CALLIGRAPHY_SHA256 + '@anxinboard.local'
_PNG_BASE64 = ''


def _invalid():
    raise ValueError('MAIL_INLINE_ASSET_INVALID')


def get_calligraphy_png() -> bytes:
    try:
        raw = base64.b64decode(_PNG_BASE64, validate=True)
    except (ValueError, TypeError):
        _invalid()
    if (len(raw) > 65536 or not raw.startswith(b'\x89PNG\r\n\x1a\n')
            or hashlib.sha256(raw).hexdigest() != CALLIGRAPHY_SHA256):
        _invalid()
    return raw


class _AssetParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.markers = []
        self.images = []
        self.cid_references = []

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag == 'meta' and attributes.get('name') == 'anxin-mail-render':
            if len(attributes) != len(attrs):
                _invalid()
            self.markers.append(attributes.get('content'))
        if tag == 'img':
            if len(attributes) != len(attrs):
                _invalid()
            self.images.append(attributes.get('src'))
        for _, value in attrs:
            if isinstance(value, str) and value.strip().lower().startswith('cid:'):
                self.cid_references.append(value)

    handle_startendtag = handle_starttag


def validate_inline_assets(html: str) -> tuple[tuple[str, bytes], ...]:
    """Only the fixed v4-v11 image resolves. Legacy no-CID HTML is untouched."""
    if type(html) is not str:
        _invalid()
    parser = _AssetParser()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        _invalid()
    if not parser.markers and not parser.cid_references:
        return ()
    source = 'cid:' + CALLIGRAPHY_CID
    if (parser.markers not in (['v4'], ['v5'], ['v6'], ['v7'], ['v8'], ['v9'], ['v10'], ['v11']) or parser.images != [source]
            or parser.cid_references != [source]):
        _invalid()
    return ((CALLIGRAPHY_CID, get_calligraphy_png()),)


def standalone_customer_html(html: str) -> str | None:
    """V7-V9 attachments use the exact body and sole embedded, digest-checked asset."""
    assets = validate_inline_assets(html)
    parser = _AssetParser()
    parser.feed(html)
    parser.close()
    if parser.markers not in (['v7'], ['v8'], ['v9'], ['v10'], ['v11']):
        return None
    cid, png = assets[0]
    source = 'cid:' + cid
    # Renderer owns this exact token. Reject alternate encodings rather than repair HTML.
    token = 'src="' + source + '"'
    if html.count(token) != 1:
        _invalid()
    embedded = 'data:image/png;base64,' + base64.b64encode(png).decode('ascii')
    return html.replace(token, 'src="' + embedded + '"', 1)
